/* prog36_pascal_triangle.c
 * Re‑implementation of the original program’s behaviour.
 *
 *   - No argument      → prints "NO_INPUT"
 *   - Argument not a non‑negative decimal integer → prints "BAD_INPUT"
 *   - n == 0          → prints "EMPTY"
 *   - n > 60          → prints "OUT_OF_RANGE"
 *   - otherwise       → prints the first n rows of Pascal's triangle
 *
 * Each row is printed on its own line, numbers are separated by a single space,
 * and no trailing space is printed.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* --------------------------------------------------------------- */
    /* 1. Argument handling                                            */
    /* --------------------------------------------------------------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long long n = strtoll(argv[1], &endptr, 10);

    /* Invalid conversion or extra characters */
    if (errno != 0 || endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    if (n > 60) {               /* original limits to 60 rows */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* --------------------------------------------------------------- */
    /* 2. Generate and print Pascal's triangle                          */
    /* --------------------------------------------------------------- */
    unsigned long long row[61] = {0};

    for (int r = 0; r < n; ++r) {
        /* Compute current row in‑place (right‑to‑left) */
        row[r] = 1;                     // last element is always 1
        for (int c = r - 1; c > 0; --c) {
            row[c] = row[c] + row[c - 1];
        }
        row[0] = 1;                     // first element is always 1

        /* Print the row */
        for (int c = 0; c <= r; ++c) {
            if (c) putchar(' ');
            printf("%llu", row[c]);
        }
        putchar('\n');
    }

    return 0;
}
